(() => {
  'use strict';
  const store = window.STORE;
  const main = document.querySelector('#main-content');
  const header = document.querySelector('#site-header');
  const menu = document.querySelector('#menu-dialog');
  const cartDialog = document.querySelector('#cart-dialog');
  const editorialDialog = document.querySelector('#editorial-dialog');
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  const currency = value => new Intl.NumberFormat('pt-BR', {style:'currency',currency:'BRL'}).format(Number(value) || 0);
  const icons = {
    arrow:'<path d="M3 12h17M14 6l6 6-6 6"/>',
    down:'<path d="m6 9 6 6 6-6"/>',
    left:'<path d="m14 5-7 7 7 7"/>',
    right:'<path d="m9 5 7 7-7 7"/>',
    bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    ruler:'<path d="m3 16 13-13 5 5L8 21 3 16Z"/><path d="m6 13 3 3m0-6 3 3m0-6 3 3m0-6 3 3"/>',
    needle:'<path d="M8 20 19 3a1.4 1.4 0 0 0-2-1L5 18c-3 4 4 5 5 1"/><path d="m15.5 6.5 2-3M4 7c2-3 6-3 8-1"/>',
    leaf:'<path d="M20 3C8 3 3 7 4 14s8 8 12 2 4-13 4-13Z"/><path d="M3 22 16 8M7 14l1-6m3 2 6 1"/>',
    truck:'<path d="M2 6h12v12H2V6ZM14 10h4l4 4v4h-8"/><path d="M18 10v5h4"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
    star:'<path d="m12 2 3 6.5 7 1-5 5 1 7-6-3.5-6 3.5 1-7-5-5 7-1L12 2Z"/>',
    user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-4a8 8 0 0 1 16 0v4"/>',
    play:'<path d="m8 4 12 8-12 8V4Z"/>',
    pause:'<path d="M8 5v14M16 5v14"/>',
    filters:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2" fill="var(--paper)"/><circle cx="16" cy="12" r="2" fill="var(--paper)"/><circle cx="10" cy="18" r="2" fill="var(--paper)"/>',
    scroll:'<path d="M12 2v19m-5-5 5 5 5-5"/>',
    check:'<path d="m5 12 4 4L20 5"/>'
  };
  const icon = (name, className='') => `<svg ${className ? `class="${className}"` : ''} viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
  const allCategories = store.categories.flatMap(category => [category,...(category.children || []).map(child => ({...child,parent:category.id}))]);
  const categoryById = id => allCategories.find(category => category.id === id);
  let isHome = true;
  let heroTimer;
  let editorialTimer;
  let toastTimer;
  let currentHero = 0;
  let heroPaused = reduceMotion;
  let serviceIndex = 0;
  let currentEditorial = 0;
  let hasRendered = false;
  let cart = [];
  try { const saved = JSON.parse(localStorage.getItem('atelier-cart-v1') || '[]'); if(Array.isArray(saved)) cart = saved.filter(line => store.products.some(product => product.id === line.id) && Number.isFinite(line.quantity) && line.quantity > 0).map(line=>({...line,quantity:Math.min(99,Math.floor(line.quantity))})); } catch (_) {}
  const editorialSlides = [
    {image:'assets/hero-linen.webp',alt:'Modelo com camisa de linho claro em um pátio de pedra',eyebrow:'ESSENCIAIS · UM NOVO OLHAR',title:'O essencial,<br>com alma.',description:'Texturas naturais. Formas leves.<br>Tempo para ser você.',category:'linhos-essenciais',link:'Explore a coleção',editorialTitle:'No seu próprio tempo.',editorialText:'Um convite a desacelerar e encontrar beleza no que é simples.'},
    {image:'assets/editorial-atelier.webp',alt:'Mãos trabalhando um tecido de linho em uma mesa de ateliê',eyebrow:'UNIVERSO ATELIER · OS DETALHES',title:'A beleza<br>do fazer.',description:'Um olhar atento às texturas,<br>aos gestos e aos pequenos detalhes.',category:'bordadas',link:'Conheça o universo Atelier',editorialTitle:'O valor dos detalhes.',editorialText:'Textura, luz e o cuidado de um gesto. Uma inspiração para o nosso universo.'},
    {image:'assets/editorial-feminino.webp',alt:'Modelo com vestido de linho marfim junto a um arco de pedra',eyebrow:'PARA ELA · LEVEZA NATURAL',title:'Leveza<br>em cada gesto.',description:'Formas que acolhem.<br>Um estilo que é só seu.',category:'feminino',link:'Explore o feminino',editorialTitle:'Leveza que acompanha.',editorialText:'Formas livres e tons naturais para viver os dias com mais calma.'}
  ];
  function updateHeader(){ header.classList.toggle('is-solid',!isHome || window.scrollY > 40); }
  window.addEventListener('scroll',updateHeader,{passive:true});
  function announce(message){ const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('is-visible'),4200); }
  function setDialogState(){ document.body.classList.toggle('has-dialog',Boolean(document.querySelector('dialog[open]')));document.querySelector('#open-menu').setAttribute('aria-expanded',String(menu.open)); }
  function openDialog(dialog){ if(!dialog.open){clearInterval(heroTimer);dialog.showModal();setDialogState();} }
  function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());setDialogState();}
  document.querySelectorAll('dialog').forEach(dialog=>{
    dialog.querySelector('.close-dialog')?.addEventListener('click',()=>dialog.close());
    dialog.addEventListener('close',()=>{setDialogState();if(dialog===editorialDialog)clearInterval(editorialTimer);restartHero();});
    dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left || event.clientX>rect.right || event.clientY<rect.top || event.clientY>rect.bottom)dialog.close();}});
  });
  function openMenu(expandProducts=false,focusSearch=false){
    if(expandProducts){document.querySelector('#products-toggle').setAttribute('aria-expanded','true');document.querySelector('#products-list').hidden=false;}
    openDialog(menu);
    document.querySelector('#menu-navigation').scrollTop=0;
    if(focusSearch)document.querySelector('#search-input').focus();
  }
  document.querySelector('#open-menu').addEventListener('click',()=>openMenu());
  document.querySelector('#open-search').addEventListener('click',()=>openMenu(false,true));
  document.querySelector('#open-cart').addEventListener('click',()=>{renderCart();openDialog(cartDialog);});
  document.querySelector('#back-top').addEventListener('click',()=>window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'}));
  document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView();});
  document.querySelectorAll('[data-brand]').forEach(node=>node.textContent=store.brand);
  document.querySelectorAll('[data-brand-title]').forEach(node=>node.textContent=store.brandTitle);
  document.querySelector('#copyright-year').textContent=new Date().getFullYear();
  if(store.instagram && /^https:\/\//.test(store.instagram)){const social=document.querySelector('.footer-social');social.href=store.instagram;social.target='_blank';social.rel='noopener noreferrer';social.setAttribute('aria-label',`Instagram ${store.brandTitle}`);social.querySelector('span').textContent='Instagram';}
  function categoryLink(category, className='menu-category'){return `<a href="#/colecao/${encodeURIComponent(category.id)}" class="${className}" data-category-link="${escape(category.id)}">${escape(category.label)}</a>`;}
  function renderMenu(){
    document.querySelector('#menu-navigation').innerHTML=`<button class="menu-main-item catalog-toggle" id="products-toggle" aria-expanded="false" aria-controls="products-list">Produtos ${icon('down')}</button><div class="menu-catalog" id="products-list" hidden><a class="menu-all" href="#/colecao/todos">Ver todos os produtos</a>${store.categories.map(category=>category.children ? `<button class="menu-category catalog-toggle group" data-toggle="sub-${escape(category.id)}" aria-expanded="false" aria-controls="sub-${escape(category.id)}">${escape(category.label)}${icon('down')}</button><div class="menu-subcategories" id="sub-${escape(category.id)}" hidden><a class="menu-all" href="#/colecao/${encodeURIComponent(category.id)}">Ver tudo em ${escape(category.label)}</a>${category.children.map(child=>categoryLink(child)).join('')}</div>` : categoryLink(category)).join('')}</div>${store.infoPages.slice(0,7).map(page=>`<a class="menu-main-item" href="#/pagina/${encodeURIComponent(page.id)}">${escape(page.label)}</a>`).join('')}`;
    document.querySelector('#products-toggle').addEventListener('click',event=>toggleDisclosure(event.currentTarget,'products-list'));
    document.querySelectorAll('[data-toggle]').forEach(button=>button.addEventListener('click',()=>toggleDisclosure(button,button.dataset.toggle)));
  }
  function toggleDisclosure(button,id){const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));document.getElementById(id).hidden=expanded;}
  document.querySelector('#menu-search').addEventListener('submit',event=>{event.preventDefault();const value=document.querySelector('#search-input').value.trim();if(value){closeDialogs();navigate(`#/buscar/${encodeURIComponent(value)}`);}});
  function navigate(hash){if(location.hash===hash){route();}else{location.hash=hash;}}
  document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#/"]');if(link){closeDialogs();if(link.hash===location.hash){event.preventDefault();route();}}});
  function breadcrumb(title,parent){return `<nav class="breadcrumb" aria-label="Localização"><a href="#/">Início</a><span aria-hidden="true">/</span>${parent ? `<a href="#/colecao/todos">Coleções</a><span aria-hidden="true">/</span>`:''}<span aria-current="page">${escape(title)}</span></nav>`;}
  function newsletter(){return `<section class="newsletter" id="novidades"><span class="eyebrow">Uma boa novidade merece ser compartilhada</span><h2>Receba todas as novidades</h2><p>Novas coleções, inspirações e um pouco do nosso universo.</p><form class="newsletter-form" id="newsletter-form"><label for="newsletter-email" class="sr-only">Seu melhor e-mail</label><input type="email" id="newsletter-email" name="email" placeholder="Seu melhor e-mail" autocomplete="email" required aria-describedby="newsletter-disclaimer"><button type="submit">Quero receber ${icon('arrow')}</button></form><small id="newsletter-disclaimer">Inscrições em breve. Por enquanto, conheça nossas coleções.</small><p class="newsletter-status" id="newsletter-status" role="status"></p></section>`;}
  function bindNewsletter(){document.querySelector('#newsletter-form')?.addEventListener('submit',event=>{event.preventDefault();document.querySelector('#newsletter-status').textContent='As inscrições ainda não estão abertas. Seu e-mail não foi enviado nem armazenado.';});}
  function renderHome(){
    currentHero=0;serviceIndex=0;heroPaused=reduceMotion;
    const services=[
      {icon:'ruler',title:'O caimento ideal',text:'Encontre o seu tamanho no guia de medidas.',page:'guia-de-medidas'},
      {icon:'needle',title:'Ajustes & sob medida',text:'Um olhar atento a cada detalhe.',page:'sob-medida'},
      {icon:'leaf',title:'Cuidado que permanece',text:'Pequenos cuidados, uma nova história.',page:'cuidados'},
      {icon:'truck',title:'Envios & entregas',text:'Tudo o que você precisa saber para receber.',page:'envios'},
      {icon:'star',title:`Fidelidade ${store.brandTitle}`,text:'Um espaço para estar cada vez mais perto.',page:'fidelidade'}
    ];
    const first=editorialSlides[0];
    main.innerHTML=`<section class="hero" aria-roledescription="carrossel" aria-label="Destaques da loja"><div class="hero-slides">${editorialSlides.map((slide,index)=>`<div class="hero-slide ${index===0?'is-active':''}" aria-hidden="${index!==0}"><img src="${slide.image}" alt="${slide.alt}" ${index===0?'fetchpriority="high" loading="eager"':'loading="lazy"'} width="${index===0?'1672':index===1?'1536':'1122'}" height="${index===0?'941':index===1?'1024':'1402'}"></div>`).join('')}</div><div class="hero-shade"></div><div class="hero-copy" id="hero-copy"><span class="eyebrow">${first.eyebrow}</span><h1>${first.title}</h1><p>${first.description}</p><a href="#/colecao/${first.category}" class="text-link">${first.link}${icon('arrow')}</a></div><span class="hero-slider-label">EDITORIAL · 2026</span><div class="hero-dots" aria-label="Escolher destaque">${editorialSlides.map((_,index)=>`<button class="hero-dot ${index===0?'is-active':''}" data-slide="${index}" aria-label="Ir para destaque ${index+1}" aria-pressed="${index===0}"></button>`).join('')}</div><div class="hero-bottom"><a class="hero-scroll" href="#colecoes">${icon('scroll')}<span>ROLE PARA DESCOBRIR</span></a><div class="slider-controls"><button id="pause-hero" class="icon-button pause-slider" aria-label="${heroPaused?'Reproduzir':'Pausar'} carrossel" aria-pressed="${heroPaused}">${icon(heroPaused?'play':'pause')}</button><button id="previous-hero" class="icon-button" aria-label="Destaque anterior">${icon('left')}</button><span class="slide-index"><span id="current-slide">01</span><span class="total">03</span></span><button id="next-hero" class="icon-button" aria-label="Próximo destaque">${icon('right')}</button></div></div></section>
      <section class="service-strip" aria-label="Serviços e cuidados"><button class="service-nav prev icon-button" aria-label="Serviço anterior">${icon('left')}</button><div class="service-window"><div class="service-track">${services.map(service=>`<a href="#/pagina/${service.page}" class="service-item">${icon(service.icon)}<h3>${service.title}</h3><p>${service.text}</p></a>`).join('')}</div></div><button class="service-nav next icon-button" aria-label="Próximo serviço">${icon('right')}</button><div class="service-dots" aria-hidden="true"></div></section>
      <section class="collection-section" id="colecoes" aria-label="Explore nossas coleções"><div class="section-kicker"><span class="eyebrow">Um universo para explorar</span><span>Escolhas que fazem sentido.</span></div><div class="collection-grid"><a href="#/colecao/linhos-essenciais" class="collection-tile"><img src="assets/hero-linen.webp" alt="Linho claro e tons naturais em um pátio ensolarado" loading="lazy" width="1672" height="941"><span class="tile-number">01 / ESSENCIAIS</span><div class="tile-copy"><span class="eyebrow">O tempo passa. O essencial fica.</span><h2>Os Clássicos<br>da Casa</h2><span class="text-link">Explore a coleção${icon('arrow')}</span></div></a><a href="#/colecao/bordadas" class="collection-tile"><img src="assets/editorial-atelier.webp" alt="Detalhes do trabalho manual com linho em um ateliê" loading="lazy" width="1536" height="1024"><div class="tile-copy"><span class="eyebrow">A beleza mora nos detalhes</span><h2>Atelier</h2><span class="text-link">Descubra${icon('arrow')}</span></div></a><a href="#/colecao/feminino" class="collection-tile"><img src="assets/editorial-feminino.webp" alt="Silhueta feminina em linho marfim" loading="lazy" width="1122" height="1402"><div class="tile-copy"><span class="eyebrow">Leve, livre, naturalmente você</span><h2>Para Ela</h2><span class="text-link">Explore a coleção${icon('arrow')}</span></div></a></div></section>
      <section class="manifesto-strip" aria-label="Nossa essência"><span>${escape(store.brandTitle)}</span><i aria-hidden="true"></i><p>Vestir o tempo com leveza.<br>Encontrar beleza no essencial.</p></section>
      <section class="editorial-cover" aria-label="Editorial da marca"><img src="assets/editorial-feminino.webp" alt="Editorial de moda em um pátio de pedra com luz natural" loading="lazy" width="1122" height="1402"><div class="editorial-caption"><span class="eyebrow">Entre a textura e o tempo</span><h2>Uma pausa.<br>Um novo olhar.</h2><button class="editorial-play" id="open-editorial"><span class="play-circle">${icon('play')}</span>Ver o editorial</button></div><span class="editorial-footnote">UNIVERSO ${escape(store.brand)} / 01</span></section>
      <div class="brand-note"><em>O essencial é aquilo que faz você se sentir bem.</em>Texturas que convidam ao toque. Formas que deixam espaço para o movimento. Um universo inspirado na beleza natural dos dias, para vestir a vida no seu próprio tempo.</div>${newsletter()}`;
    document.querySelector('#previous-hero').addEventListener('click',()=>{showHero(currentHero-1);restartHero();});
    document.querySelector('#next-hero').addEventListener('click',()=>{showHero(currentHero+1);restartHero();});
    document.querySelectorAll('[data-slide]').forEach(button=>button.addEventListener('click',()=>{showHero(Number(button.dataset.slide));restartHero();}));
    document.querySelector('#pause-hero').addEventListener('click',()=>{heroPaused=!heroPaused;const button=document.querySelector('#pause-hero');button.setAttribute('aria-label',`${heroPaused?'Reproduzir':'Pausar'} carrossel`);button.setAttribute('aria-pressed',String(heroPaused));button.innerHTML=icon(heroPaused?'play':'pause');restartHero();});
    const hero=document.querySelector('.hero');
    hero.addEventListener('mouseenter',()=>clearInterval(heroTimer));hero.addEventListener('mouseleave',restartHero);hero.addEventListener('focusin',()=>clearInterval(heroTimer));hero.addEventListener('focusout',event=>{if(!hero.contains(event.relatedTarget))restartHero();});
    let touchStart=null;
    hero.addEventListener('touchstart',event=>{touchStart={x:event.changedTouches[0].clientX,y:event.changedTouches[0].clientY};},{passive:true});
    hero.addEventListener('touchend',event=>{if(!touchStart)return;const dx=event.changedTouches[0].clientX-touchStart.x;const dy=event.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>60 && Math.abs(dx)>Math.abs(dy)*1.4){showHero(currentHero+(dx<0?1:-1));restartHero();}touchStart=null;},{passive:true});
    document.querySelector('.hero-scroll').addEventListener('click',event=>{event.preventDefault();document.querySelector('#colecoes').scrollIntoView({behavior:reduceMotion?'auto':'smooth'});});
    document.querySelector('.service-nav.prev').addEventListener('click',()=>shiftServices(-1));
    document.querySelector('.service-nav.next').addEventListener('click',()=>shiftServices(1));
    updateServices();restartHero();
    document.querySelector('#open-editorial').addEventListener('click',()=>{currentEditorial=0;showEditorial();openDialog(editorialDialog);});
    bindNewsletter();
  }
  function showHero(index){if(!isHome)return;currentHero=(index+editorialSlides.length)%editorialSlides.length;const slide=editorialSlides[currentHero];document.querySelectorAll('.hero-slide').forEach((element,i)=>{element.classList.toggle('is-active',i===currentHero);element.setAttribute('aria-hidden',String(i!==currentHero));});document.querySelectorAll('.hero-dot').forEach((element,i)=>{element.classList.toggle('is-active',i===currentHero);element.setAttribute('aria-pressed',String(i===currentHero));});document.querySelector('#hero-copy').innerHTML=`<span class="eyebrow">${slide.eyebrow}</span><h1>${slide.title}</h1><p>${slide.description}</p><a href="#/colecao/${slide.category}" class="text-link">${slide.link}${icon('arrow')}</a>`;document.querySelector('#current-slide').textContent=String(currentHero+1).padStart(2,'0');}
  function restartHero(){clearInterval(heroTimer);if(isHome && !heroPaused && !document.hidden && !document.querySelector('dialog[open]'))heroTimer=setInterval(()=>showHero(currentHero+1),8500);}
  document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInterval(heroTimer);else restartHero();});
  function serviceVisible(){return window.innerWidth<=700?1:3;}
  function shiftServices(direction){const positions=6-serviceVisible();serviceIndex=(serviceIndex+direction+positions)%positions;updateServices();}
  function updateServices(){const track=document.querySelector('.service-track');if(!track)return;const visible=serviceVisible();serviceIndex=Math.min(serviceIndex,5-visible);track.style.transform=`translateX(-${serviceIndex*100/visible}%)`;track.querySelectorAll('.service-item').forEach((item,index)=>{const shown=index>=serviceIndex && index<serviceIndex+visible;item.tabIndex=shown?0:-1;item.setAttribute('aria-hidden',String(!shown));});document.querySelector('.service-dots').innerHTML=Array.from({length:6-visible},(_,i)=>`<span class="${i===serviceIndex?'active':''}"></span>`).join('');}
  window.addEventListener('resize',()=>{if(isHome)updateServices();},{passive:true});
  function showEditorial(){const slide=editorialSlides[currentEditorial];document.querySelector('#editorial-content').innerHTML=`<div class="editorial-view"><img src="${slide.image}" alt="${slide.alt}"><div class="editorial-view-copy"><span class="eyebrow">EDITORIAL · ${String(currentEditorial+1).padStart(2,'0')} / 03</span><h2>${slide.editorialTitle}</h2><p>${slide.editorialText}</p></div><div class="editorial-view-controls"><button class="icon-button" id="editorial-previous" aria-label="Foto anterior">${icon('left')}</button><span>${currentEditorial+1} / 3</span><button class="icon-button" id="editorial-next" aria-label="Próxima foto">${icon('right')}</button></div></div>`;document.querySelector('#editorial-previous').addEventListener('click',()=>{currentEditorial=(currentEditorial+2)%3;showEditorial();document.querySelector('#editorial-previous').focus();});document.querySelector('#editorial-next').addEventListener('click',()=>{currentEditorial=(currentEditorial+1)%3;showEditorial();document.querySelector('#editorial-next').focus();});}
  function productsIn(category){if(!category || category.id==='todos')return [...store.products];const ids=[category.id,...(category.children || []).map(child=>child.id)];return store.products.filter(product=>ids.includes(product.category)|| (product.categories||[]).some(id=>ids.includes(id)));}
  function renderCatalog(id){
    const category=id==='todos'?{id:'todos',label:'Todas as coleções',description:'Descubra o universo Atelier. Um novo olhar para o essencial.'}:categoryById(id);
    if(!category){renderNotFound();return;}
    const products=productsIn(category);
    const childCategories=category.children || (category.parent?categoryById(category.parent).children:null);
    const chips=childCategories || (id==='todos'?store.categories.filter(item=>['novidades','linhos-essenciais','feminino','sports-club'].includes(item.id)):[]);
    main.innerHTML=`<div class="interior-page"><section class="page-heading">${breadcrumb(category.label,true)}<span class="eyebrow">AS COLEÇÕES · ${escape(store.brand)}</span><h1>${escape(category.label)}</h1><p>${escape(category.description)}</p>${chips.length?`<nav class="catalog-chips" aria-label="Subcoleções">${chips.map(child=>`<a href="#/colecao/${child.id}" class="catalog-chip ${child.id===id?'is-selected':''}">${escape(child.label)}</a>`).join('')}</nav>`:''}</section><div class="catalog-toolbar"><button id="catalog-categories">${icon('filters')}Categorias</button><span class="catalog-count">${products.length} ${products.length===1?'produto':'produtos'}</span><label class="sort-field"><span>Ordenar por</span><select id="sort-products" aria-label="Ordenar produtos"><option value="featured">Mais relevantes</option><option value="price-asc">Menor preço</option><option value="price-desc">Maior preço</option><option value="name">Nome A–Z</option></select></label></div>${products.length?`<div class="product-grid" id="product-grid">${products.map(productCard).join('')}</div>`:`<section class="empty-collection"><div class="empty-symbol">${icon('leaf')}</div><span class="eyebrow">EM BREVE, UM NOVO CAPÍTULO</span><h2>Uma nova seleção<br>está a caminho.</h2><p>As peças desta coleção serão apresentadas em breve. Enquanto isso, sinta-se à vontade para explorar o nosso universo.</p><button class="solid-button" id="explore-categories">Explorar as coleções${icon('arrow')}</button><br><a class="text-link" href="#/">Voltar ao início</a></section><section class="catalog-inspiration"><img src="assets/editorial-atelier.webp" alt="Texturas e gestos de um ateliê" loading="lazy"><div><span class="eyebrow">O UNIVERSO ${escape(store.brand)}</span><h3>Os detalhes<br>contam histórias.</h3><a class="text-link" href="#/pagina/sobre">Conheça a nossa essência${icon('arrow')}</a></div></section>`}</div>`;
    document.querySelector('#catalog-categories').addEventListener('click',()=>openMenu(true));
    document.querySelector('#explore-categories')?.addEventListener('click',()=>openMenu(true));
    document.querySelector('#sort-products').addEventListener('change',event=>{const sorted=[...products];if(event.target.value==='price-asc')sorted.sort((a,b)=>a.price-b.price);if(event.target.value==='price-desc')sorted.sort((a,b)=>b.price-a.price);if(event.target.value==='name')sorted.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const grid=document.querySelector('#product-grid');if(grid)grid.innerHTML=sorted.map(productCard).join('');});
    document.title=`${category.label} — ${store.brand}`;
  }
  function productCard(product){return `<a class="product-card" href="#/produto/${encodeURIComponent(product.id)}"><div class="product-image"><img src="${escape(product.image)}" alt="${escape(product.name)}" loading="lazy"></div><h2>${escape(product.name)}</h2><p class="price">${currency(product.price)}</p></a>`;}
  function renderProduct(id){const product=store.products.find(item=>item.id===id);if(!product){renderNotFound();return;}main.innerHTML=`<div class="interior-page"><div class="product-detail"><img class="product-detail-image" src="${escape(product.image)}" alt="${escape(product.name)}"><div class="product-detail-copy"><span class="eyebrow">${escape(categoryById(product.category)?.label||'COLEÇÃO ATELIER')}</span><h1>${escape(product.name)}</h1><p class="price">${currency(product.price)}</p><p>${escape(product.description)}</p><form id="add-product"><div class="product-options"><label>Tamanho<select name="size" required><option value="">Selecione</option>${(product.sizes || ['Único']).map(size=>`<option value="${escape(size)}">${escape(size)}</option>`).join('')}</select></label><label>Quantidade<select name="quantity">${[1,2,3,4,5].map(q=>`<option>${q}</option>`).join('')}</select></label></div><button class="solid-button" type="submit">Adicionar à sacola${icon('bag')}</button></form><p class="cart-order-note">Esta loja está em apresentação. Os pagamentos ainda não estão disponíveis.</p><a class="text-link" style="margin-top:28px" href="#/pagina/guia-de-medidas">Guia de medidas${icon('arrow')}</a></div></div></div>`;document.querySelector('#add-product').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const size=data.get('size');const quantity=Number(data.get('quantity'));const existing=cart.find(line=>line.id===id && line.size===size);if(existing)existing.quantity=Math.min(99,existing.quantity+quantity);else cart.push({id,size,quantity});persistCart();renderCart();openDialog(cartDialog);});document.title=`${product.name} — ${store.brand}`;}
  function renderInfo(id){const page=store.infoPages.find(item=>item.id===id);if(!page){renderNotFound();return;}main.innerHTML=`<div class="interior-page"><section class="page-heading">${breadcrumb(page.label)}<span class="eyebrow">${escape(page.eyebrow)}</span><h1>${escape(page.title)}</h1><p>${escape(page.intro)}</p></section><div class="info-body"><nav class="info-sidebar" aria-label="Informações da loja">${store.infoPages.map(item=>`<a href="#/pagina/${item.id}" class="${item.id===id?'is-current':''}" ${item.id===id?'aria-current="page"':''}>${escape(item.label)}</a>`).join('')}</nav><article class="info-copy">${page.sections.map(section=>`<section><h2>${escape(section.title)}</h2><p>${escape(section.text)}</p></section>`).join('')}${id==='contato'&&store.contactEmail?`<a class="text-link" href="mailto:${escape(store.contactEmail)}">${escape(store.contactEmail)}${icon('arrow')}</a>`:''}<a class="text-link" href="#/colecao/todos">Explore as coleções${icon('arrow')}</a></article></div></div>`;document.title=`${page.title} — ${store.brand}`;}
  function renderAccount(mode){const register=mode==='cadastro';main.innerHTML=`<div class="interior-page"><section class="page-heading">${breadcrumb('Minha conta')}<span class="eyebrow">UM ESPAÇO PARA VOCÊ</span><h1>Minha conta</h1><p>Seu próximo capítulo no universo ${escape(store.brandTitle)}.</p></section><section class="account-page-content"><nav class="account-tabs" aria-label="Acesso à conta"><a href="#/conta/login" class="${register?'':'active'}" ${register?'':'aria-current="page"'}>Login</a><a href="#/conta/cadastro" class="${register?'active':''}" ${register?'aria-current="page"':''}>Cadastre-se</a></nav>${icon('user')}<h2>${register?'Vamos nos conhecer<br>em breve.':'Seu espaço está<br>chegando.'}</h2><p>${register?'Os cadastros serão abertos junto com o lançamento da loja. Até lá, descubra as nossas coleções e inspirações.':'A área do cliente estará disponível no lançamento da loja, para acompanhar seus pedidos e novidades.'}</p><a class="solid-button" href="#/colecao/todos">Explorar as coleções${icon('arrow')}</a></section></div>`;document.title=`${register?'Cadastre-se':'Minha conta'} — ${store.brand}`;}
  function renderSearch(query){const term=normalize(query);const matches=term?allCategories.filter(category=>normalize(`${category.label} ${category.referenceLabel} ${category.description}`).includes(term)):allCategories;const products=term?store.products.filter(product=>normalize(`${product.name} ${product.description}`).includes(term)):[];main.innerHTML=`<div class="interior-page"><section class="page-heading">${breadcrumb('Busca')}<span class="eyebrow">DESCUBRA O SEU ESSENCIAL</span><h1>${query?'Resultados da busca':'O que você procura?'}</h1><form class="search-main-form" id="page-search" role="search"><label for="page-search-input" class="sr-only">Buscar produtos e coleções</label><input id="page-search-input" type="search" value="${escape(query)}" placeholder="Busque por linho, feminino, novidades…" autocomplete="off" required><button aria-label="Buscar">${icon('search')}</button></form></section><section class="search-results"><p class="search-results-heading">${matches.length} ${matches.length===1?'coleção encontrada':'coleções encontradas'}${query?` para “${escape(query)}”`:''}</p>${matches.length?matches.map(category=>`<a href="#/colecao/${category.id}" class="search-result"><div><h2>${escape(category.label)}</h2><p>${escape(category.description)}</p></div>${icon('arrow')}</a>`).join(''):`<h2 class="no-results">Ainda não encontramos essa seleção.</h2><p style="font-size:12px;color:var(--muted)">Experimente buscar por “linho”, “feminino” ou “sports”.</p><a href="#/colecao/todos" class="text-link" style="margin-top:26px">Ver todas as coleções${icon('arrow')}</a>`}<p class="search-empty-note">${products.length?`${products.length} produtos encontrados.`:'Os produtos serão apresentados em breve. Por enquanto, você pode explorar as coleções.'}</p></section>${products.length?`<div class="product-grid">${products.map(productCard).join('')}</div>`:''}</div>`;document.querySelector('#page-search').addEventListener('submit',event=>{event.preventDefault();const value=document.querySelector('#page-search-input').value.trim();if(value)navigate(`#/buscar/${encodeURIComponent(value)}`);});document.title=`Busca${query?`: ${query}`:''} — ${store.brand}`;}
  function renderNotFound(){main.innerHTML=`<div class="interior-page"><section class="empty-collection" style="padding-top:100px"><span class="eyebrow">UM NOVO CAMINHO</span><h1 style="font-size:43px;margin:22px 0">Vamos voltar<br>ao essencial?</h1><p>Não encontramos esta página. Explore nossas coleções para continuar.</p><a class="solid-button" href="#/colecao/todos">Ver as coleções${icon('arrow')}</a></section></div>`;document.title=`Página não encontrada — ${store.brand}`;}
  function persistCart(){try{localStorage.setItem('atelier-cart-v1',JSON.stringify(cart));}catch(_){}updateCartCount();}
  function updateCartCount(){const count=cart.reduce((total,line)=>total+line.quantity,0);document.querySelector('#cart-count').textContent=count;document.querySelector('#cart-title-count').textContent=`(${count})`;document.querySelector('#open-cart').setAttribute('aria-label',`Abrir sacola, ${count} ${count===1?'item':'itens'}`);}
  function renderCart(){updateCartCount();const content=document.querySelector('#cart-content');if(!cart.length){content.innerHTML=`<div class="empty-cart">${icon('bag')}<h3>Sua sacola está vazia.</h3><p>A próxima peça da sua história<br>ainda está por aqui.</p><a href="#/colecao/todos" class="solid-button">Explorar as coleções${icon('arrow')}</a></div><p class="cart-preview-note">Novas coleções serão apresentadas em breve.</p>`;return;}let total=0;content.innerHTML=`<div class="cart-lines">${cart.map((line,index)=>{const product=store.products.find(item=>item.id===line.id);total+=product.price*line.quantity;return `<div class="cart-line"><img src="${escape(product.image)}" alt="${escape(product.name)}"><div><h3>${escape(product.name)}</h3><p>Tamanho ${escape(line.size)}</p><p class="line-price">${currency(product.price*line.quantity)}</p><div class="cart-quantity"><button data-quantity="${index}" data-change="-1" aria-label="Diminuir quantidade de ${escape(product.name)}">−</button><span>${line.quantity}</span><button data-quantity="${index}" data-change="1" aria-label="Aumentar quantidade de ${escape(product.name)}">+</button></div></div><button class="cart-remove" data-remove="${index}" aria-label="Remover ${escape(product.name)}">×</button></div>`;}).join('')}</div><div class="cart-total"><span>Subtotal</span><span>${currency(total)}</span></div><a href="#/colecao/todos" class="outline-button">Continuar explorando${icon('arrow')}</a><p class="cart-order-note">Os pagamentos estarão disponíveis no lançamento da loja. Nenhuma compra será realizada nesta prévia.</p>`;content.querySelectorAll('[data-quantity]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.quantity);cart[index].quantity=Math.min(99,cart[index].quantity+Number(button.dataset.change));if(cart[index].quantity<=0)cart.splice(index,1);persistCart();renderCart();}));content.querySelectorAll('[data-remove]').forEach(button=>button.addEventListener('click',()=>{cart.splice(Number(button.dataset.remove),1);persistCart();renderCart();}));}
  function route(){clearInterval(heroTimer);clearInterval(editorialTimer);closeDialogs();const hash=location.hash||'#/';const parts=hash.replace(/^#\/?/,'').split('/');let id='';try{id=decodeURIComponent(parts.slice(1).join('/'));}catch(_){id='';}isHome=!parts[0];if(isHome){renderHome();document.title=`${store.brand} — O essencial, com alma`;}else if(parts[0]==='colecao'){renderCatalog(id||'todos');}else if(parts[0]==='pagina'){renderInfo(id);}else if(parts[0]==='buscar'){renderSearch(id);}else if(parts[0]==='conta'){renderAccount(id);}else if(parts[0]==='produto'){renderProduct(id);}else{renderNotFound();}document.querySelectorAll('[data-category-link]').forEach(link=>{const current=parts[0]==='colecao'&&link.dataset.categoryLink===id;link.classList.toggle('is-current',current);if(current)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});window.scrollTo({top:0,behavior:'instant'});updateHeader();if(hasRendered)main.focus({preventScroll:true});hasRendered=true;}
  window.addEventListener('hashchange',route);
  renderMenu();updateCartCount();route();
})();
